package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class RiskAssessmentsAcceptance {
 static String api(String id){return "/api/openservice/risks/"+id+"/assessment";}
 static String record(String id){return "/api/now/table/risk/"+id;}
 static String tasks(String id){return "/api/openservice/records/risk/"+id+"/work-tasks";}
 static String reviews(String id){return "/api/openservice/records/risk/"+id+"/approvals";}
 static String[] setup(WorkflowSupport h)throws Exception{h.account("RiskAssessor","agent");h.account("RiskOwner","agent");h.account("RiskOther","agent");h.account("RiskReader","reader");String group=h.add("sys_user_group").get("sys_id").toString();for(String name:List.of("RiskAssessor","RiskOwner"))RecordScopesAcceptance.member(h,group,FieldDispatchAcceptance.uid(h,name),true);String id=result(h.json("POST","/api/now/table/risk",map("short_description","Supply interruption <script>","description","Risk description"),auth("RiskAssessor"))).get("sys_id").toString();return new String[]{id,group};}
 static Map<String,Object> body(WorkflowSupport h,String id)throws Exception{var p=get(h,api(id),"RiskAssessor");return map("revision",p.get("revision"),"record_revision",Integer.parseInt(object(p.get("record")).get("sys_mod_count").toString()),"likelihood",4,"impact",5,"residual_likelihood",2,"residual_impact",3,"response","mitigate","rationale","Documented supply exposure <script>","treatment","Qualify a replacement supplier","owner","RiskOwner","review_on","2030-12-31");}
 static Map<String,Object> save(WorkflowSupport h,String id,Map<String,Object> b)throws Exception{return result(h.json("POST",api(id),b,auth("RiskAssessor")));}
 static void state(WorkflowSupport h,String id,String state,int expected)throws Exception{var r=h.json("PATCH",record(id),map("state",state),auth("RiskAssessor"));assertEquals(expected,r.statusCode(),html(r));}
 static Map<String,Object> taskBody(WorkflowSupport h,String id,String operation)throws Exception{var page=get(h,tasks(id),"RiskAssessor");var task=objects(page.get("tasks"));var b=map("operation",operation,"record_revision",Integer.parseInt(object(page.get("parent")).get("sys_mod_count").toString()),"revision",operation.equals("create")?object(page.get("plan")).get("revision"):task.getLast().get("revision"));if(!operation.equals("create"))b.put("task_id",task.getLast().get("task_id"));return b;}
 static void work(WorkflowSupport h,String id,String group)throws Exception{var b=taskBody(h,id,"create");b.putAll(map("summary","Qualify replacement supplier","details","Verify an alternative supply route","group_id",group,"required",true,"predecessors",List.of()));result(h.json("POST",tasks(id),b,auth("RiskAssessor")));result(h.json("POST",tasks(id),taskBody(h,id,"claim"),auth("RiskAssessor")));b=taskBody(h,id,"complete");b.put("outcome","Alternative supplier qualification verified");result(h.json("POST",tasks(id),b,auth("RiskAssessor")));}
 static Map<String,Object> proposal(WorkflowSupport h,String id,String owner)throws Exception{return map("expected_revision",Integer.parseInt(get(h,record(id),"RiskAssessor").get("sys_mod_count").toString()),"approver",owner,"target_state","monitor","reason","Review the current assessed risk and completed treatment");}
 static String approve(WorkflowSupport h,String id)throws Exception{String approval=result(h.json("POST",reviews(id),proposal(h,id,"RiskOwner"),auth("RiskAssessor"))).get("approval_id").toString();result(h.json("POST",reviews(id)+"/"+approval+"/decision",map("decision","approved","comment","Treatment and residual exposure reviewed"),auth("RiskOwner")));return approval;}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(false,get(h,api(id),"RiskAssessor").get("current"));state(h,id,"assess",200);state(h,id,"respond",409);var assessment=save(h,id,body(h,id));assertEquals(20,object(assessment.get("assessment")).get("score"));assertEquals(6,object(assessment.get("assessment")).get("residual_score"));assertEquals(true,assessment.get("current"));assertEquals(1,objects(assessment.get("history")).size());state(h,id,"respond",200);assertEquals(400,h.json("POST",reviews(id),proposal(h,id,"RiskOwner"),auth("RiskAssessor")).statusCode());state(h,id,"monitor",409);work(h,id,ids[1]);assertEquals(400,h.json("POST",reviews(id),proposal(h,id,"RiskOther"),auth("RiskAssessor")).statusCode());approve(h,id);state(h,id,"monitor",200);assertEquals(false,get(h,api(id),"RiskAssessor").get("can_edit"));new Store(h.environment);assertEquals(20,object(get(h,api(id),"RiskOwner").get("assessment")).get("score"));assertEquals(409,h.json("PATCH",record(id),map("description","Unreviewed change"),auth("RiskAssessor")).statusCode());assertEquals(409,h.json("POST",api(id),body(h,id),auth("RiskAssessor")).statusCode());state(h,id,"retired",200);state(h,id,"assess",200);var next=body(h,id);next.putAll(map("response","accept","likelihood",1,"impact",1,"residual_likelihood",1,"residual_impact",1));save(h,id,next);assertEquals(2,objects(get(h,api(id),"RiskOwner").get("history")).size());state(h,id,"respond",200);approve(h,id);state(h,id,"monitor",200);assertEquals(204,h.json("DELETE",record(id),map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_risk_assessment WHERE record_id=?",id));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(401,h.get(api(id),null).statusCode());assertEquals(403,h.get(api(id),auth("RiskReader")).statusCode());assertEquals(405,h.json("PUT",api(id),map(),auth("RiskAssessor")).statusCode());assertEquals(400,h.get(api(id)+"?q=x",auth("RiskAssessor")).statusCode());for(var change:List.of(map("extra",1),map("likelihood",0),map("impact",6),map("residual_likelihood","2"),map("residual_impact",2.5),map("response","other"),map("rationale",""),map("treatment","x".repeat(4001)),map("owner","missing"),map("owner","RiskAssessor"),map("owner","RiskReader"),map("review_on","bad"),map("review_on","2030-02-30"),map("review_on","2020-01-01"),map("revision",-1))){var bad=body(h,id);bad.putAll(change);assertEquals(400,h.json("POST",api(id),bad,auth("RiskAssessor")).statusCode());}for(String key:List.of("revision","record_revision")){var bad=body(h,id);bad.put(key,999);assertEquals(409,h.json("POST",api(id),bad,auth("RiskAssessor")).statusCode());}var b=body(h,id);b.put("response","accept");save(h,id,b);state(h,id,"assess",200);state(h,id,"respond",200);approve(h,id);state(h,id,"monitor",200);assertEquals(400,h.protectedForm("/record/risk/"+id+"/assessment",map("revision","bad"),auth("RiskAssessor")).statusCode());for(String state:List.of("assess","respond","monitor","retired"))assertEquals(409,h.json("POST","/api/openservice/import/risk?dry_run=false",List.of(map("sys_id",Values.id(),"short_description","Unreviewed imported risk","state",state)),auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var proposed=body(h,id);ProblemInvestigationsAcceptance.access(h,"risk",id,"private",FieldDispatchAcceptance.uid(h,"RiskAssessor"));assertEquals(400,h.json("POST",api(id),proposed,auth("RiskAssessor")).statusCode());assertEquals(404,h.get(api(id),auth("RiskOwner")).statusCode());result(h.json("PATCH","/api/openservice/access/risk/"+id,map("visibility","group","group_id",ids[1]),auth("admin")));assertEquals(404,h.get(api(id),auth("RiskOther")).statusCode());Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"risk");}
  for(String field:List.of("risk_score","residual_score")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"risk",schema);try{assertEquals(403,h.get(api(id),auth("RiskAssessor")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"risk",original);}}
  for(String restriction:List.of("update","description","risk_score","residual_score")){var schema=new LinkedHashMap<>(original);if(restriction.equals("update")){var roles=new LinkedHashMap<>(object(original.get("record_roles")));roles.put("update",List.of("admin"));schema.put("record_roles",roles);}else schema.put("field_rules",map(restriction,map("type","string","write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"risk",schema);try{assertEquals(false,get(h,api(id),"RiskAssessor").get("can_edit"));assertEquals(403,h.json("POST",api(id),proposed,auth("RiskAssessor")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"risk",original);}}
  var allowed=new LinkedHashMap<>(original);allowed.put("field_rules",map("description",map("type","string","write_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"risk",allowed);try{assertEquals(true,get(h,api(id),"RiskAssessor").get("can_edit"));}finally{ReferencePickerAcceptance.writeSchema(h,"risk",original);}
  proposed.put("response","accept");save(h,id,proposed);state(h,id,"assess",200);state(h,id,"respond",200);var rework=proposal(h,id,"RiskOwner");rework.put("target_state","assess");result(h.json("POST",reviews(id),rework,auth("RiskAssessor")));String approval=approve(h,id);RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"RiskOwner"),false);state(h,id,"monitor",409);RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"RiskOwner"),true);try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='RiskOwner'");db.connection.commit();}state(h,id,"monitor",409);state(h,id,"assess",200);state(h,id,"respond",409);var unavailable=body(h,id);assertEquals(400,h.json("POST",api(id),unavailable,auth("RiskAssessor")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET active=1 WHERE name='RiskOwner'");db.connection.commit();}
  var schema=new LinkedHashMap<>(original);schema.put("version",Approvals.version(original)+1);schema.put("transition_rules",map());ReferencePickerAcceptance.writeSchema(h,"risk",schema);try{assertEquals(false,get(h,api(id),"RiskAssessor").get("current"));state(h,id,"respond",409);var reassess=body(h,id);reassess.put("response","accept");save(h,id,reassess);state(h,id,"respond",200);state(h,id,"monitor",409);approve(h,id);state(h,id,"monitor",200);}finally{ReferencePickerAcceptance.writeSchema(h,"risk",original);}
 }
 static void treatment(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var b=body(h,id);b.put("response","avoid");save(h,id,b);state(h,id,"assess",200);state(h,id,"respond",200);b=taskBody(h,id,"create");b.putAll(map("summary","Pending required treatment","details","Required alternative plan","group_id",ids[1],"required",true,"predecessors",List.of()));result(h.json("POST",tasks(id),b,auth("RiskAssessor")));assertEquals(400,h.json("POST",reviews(id),proposal(h,id,"RiskOwner"),auth("RiskAssessor")).statusCode());var waive=taskBody(h,id,"waive");waive.put("reason","Explicitly waived, not evidence of completed treatment");result(h.json("POST",tasks(id),waive,auth("admin")));assertEquals(400,h.json("POST",reviews(id),proposal(h,id,"RiskOwner"),auth("RiskAssessor")).statusCode());work(h,id,ids[1]);approve(h,id);
  try(var db=h.store.open()){var row=db.one("SELECT revision,detail FROM os_risk_assessment WHERE record_id=? ORDER BY revision DESC LIMIT 1",id);var detail=object(row.get("detail"));detail.put("review_on","2000-01-01");db.update("UPDATE os_risk_assessment SET detail=? WHERE record_id=? AND revision=?",JSON.writeValueAsString(detail),id,row.get("revision"));db.connection.commit();}assertEquals(true,get(h,api(id),"RiskAssessor").get("overdue"));state(h,id,"monitor",409);state(h,id,"assess",200);b=body(h,id);b.put("response","transfer");save(h,id,b);state(h,id,"respond",200);approve(h,id);state(h,id,"monitor",200);state(h,id,"assess",200);result(h.json("PATCH",record(id),map("description","Changed risk basis"),auth("RiskAssessor")));assertEquals(false,get(h,api(id),"RiskAssessor").get("current"));state(h,id,"respond",409);
 }
 static void concurrency(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var b=body(h,id);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return h.json("POST",api(id),b,auth("RiskAssessor")).statusCode();});var c=pool.submit(()->{start.await();return h.json("POST",api(id),b,auth("RiskAssessor")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),c.get()));}assertEquals(1,objects(get(h,api(id),"RiskAssessor").get("history")).size());try(var db=h.store.open()){var detail=db.one("SELECT detail FROM os_risk_assessment WHERE record_id=?",id).get("detail");for(int n=2;n<100;n++)db.update("INSERT INTO os_risk_assessment(record_id,revision,detail) VALUES(?,?,?)",id,n,JSON.writeValueAsString(detail));db.connection.commit();}save(h,id,body(h,id));assertEquals(100,objects(get(h,api(id),"RiskAssessor").get("history")).size());assertEquals(400,h.json("POST",api(id),body(h,id),auth("RiskAssessor")).statusCode());
 }

}
